import { Inject, Logger, NotFoundException, Optional, forwardRef } from '@nestjs/common';
import { ServicesService } from '../services/services.service';
import { InfluxService } from '../influx/influx.service';
import { InvoicesService } from '../invoice/invoices.service';
import { Billing, billingScheduleConsumers } from './entities/billing.entity';
import { randomUUID } from 'crypto';
import { Process, Processor } from '@nestjs/bull';
import { CreateBillingReportDto } from './dto/createBillingReport.dto';
import { Job } from 'bull';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity';
import { CustomerService } from '../customer/customer.service';
import { OfferingService } from '../offering/offering.service';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';
import { ReadOfferingResponseData } from '../offering/dto/readOffering.dto';

@Processor('scheduler_billing_queue')
export class BillingService {
    private static readonly logger = new Logger(BillingService.name);
    constructor(
        readonly InfluxService: InfluxService,
        @Optional() @Inject(forwardRef(() => ServicesService)) readonly servicesService: ServicesService,
        @Inject(forwardRef(() => InvoicesService)) readonly invoicesService: InvoicesService,
        @Optional()
        @Inject(forwardRef(() => CustomerService))
        private readonly injectedCustomerService?: CustomerService,
        @Optional()
        @Inject(forwardRef(() => OfferingService))
        private readonly injectedOfferingService?: OfferingService
    ) {}

    get customerService(): CustomerService {
        return this.injectedCustomerService ?? this.invoicesService?.customerService;
    }

    get offeringService(): OfferingService {
        return this.injectedOfferingService ?? this.customerService?.offeringService;
    }

    /**
     * Generates the billing report (invoice + billing ledger record) for a single customer.
     * The job is emitted by the scheduler, the businessID lives on the scheduler record itself while the
     * customerId is passed along in the schedule parameters.
     */
    @Process({ name: billingScheduleConsumers.billingReport })
    async create({ data: { scheduleParameters, businessID } }: Job<SchedulerEntity>) {
        const { customerId, businessID: parameterBusinessID } = (scheduleParameters ??
            {}) as CreateBillingReportDto;
        const resolvedBusinessID = businessID ?? parameterBusinessID;
        try {
            // 1. Resolve the customer and the offering it is subscribed to, without an offering there is nothing to bill
            const offering = await this.findOfferingForCustomer({ customerId, businessID: resolvedBusinessID });
            if (!offering) {
                BillingService.logger.log(
                    `No Billing Data found for customer:${customerId} in business: ${resolvedBusinessID}`
                );
                return;
            }
            // 2. The offering billing cycle determines the time range the usage is billed for
            const { startTime, endTime } = Billing.billingCycleToTimeRange(offering.billingCycle);
            BillingService.logger.log(
                `Generating billing report for customer: ${customerId} in business: ${resolvedBusinessID} between ${startTime} and ${endTime}`
            );
            // 3. Generate the invoice off of the aggregated usage totals for the customer
            const { invoiceId } = await this.invoicesService.generateInvoiceForUsageTotal({
                businessID: resolvedBusinessID,
                customerId,
                start: startTime,
                end: endTime,
            });
            // 4. Save Billing information to the Ledger
            const entity = new Billing({
                invoiceId,
                businessID: resolvedBusinessID,
                customerId,
                startTime,
                endTime,
                billingId: randomUUID(),
            });
            const point = Billing.transformer(entity, this.InfluxService);
            await this.InfluxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, 'paigo', [point]);
            return { message: 'Created Billing Report' };
        } catch (e) {
            AuditService.publishEvent({
                message: `Error occurred while generating the billing report for customer: ${customerId} in business: ${resolvedBusinessID}`,
                data: [e],
                topic: AuditScope.ERROR,
            });
        }
    }

    private async findOfferingForCustomer({
        customerId,
        businessID,
    }: {
        customerId: string;
        businessID: string;
    }): Promise<ReadOfferingResponseData> {
        const {
            data: [customer],
        } = await this.customerService.findOne({ customerId, businessID });
        if (!customer) {
            throw new NotFoundException(`Customer with ID: ${customerId} not found`);
        }
        if (customer.offering) {
            return customer.offering;
        }
        if (customer.offeringId) {
            const {
                data: [offering],
            } = await this.offeringService.findOne({ businessID, offeringId: customer.offeringId });
            return offering;
        }
        return undefined;
    }
}

